import pypdf
reader = pypdf.PdfReader('/shared/ligu/projects/MobileWorld/src/mobile_world/tasks/definitions/native/assets/qwen3.pdf')
for i, page in enumerate(reader.pages):
    text = page.extract_text()
    if 'AIME' in text:
        print(f'=== PAGE {i+1} ===')
        # Print a snippet around AIME
        lines = text.split('\n')
        for j, line in enumerate(lines):
            if 'AIME' in line:
                start = max(0, j-2)
                end = min(len(lines), j+10)
                for k in range(start, end):
                    print(lines[k])
                print('---')
" 2>/dev/null

